WITH lines AS (SELECT id, customer_id, created_at, EXPLODE_OUTER(coupon_codes) AS element FROM carts), enriched AS (SELECT src.*, c.segment, c.country FROM lines src JOIN customers c ON src.customer_id = c.id), with_dims AS (SELECT e.*, d.email, d.signup_date FROM enriched e JOIN customers d ON e.customer_id = d.id), enriched_carts AS (SELECT a.customer_id, a.created_at, a.element, b.credit_limit FROM with_dims a LEFT JOIN customers b ON a.customer_id <=> b.id), scored AS (SELECT customer_id, created_at, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY customer_id), 4) credit_limit_share FROM enriched_carts WHERE element <> 'WELCOME5') SELECT s.customer_id, s.created_at, (SELECT MAX(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS max_account_balance FROM scored s ORDER BY created_at, customer_id DESC;
